/* word reveal for streamed text */
.w{opacity:0;filter:blur(4px);transition:opacity .5s ease,filter .5s ease}
.w.in{opacity:1;filter:blur(0)}

/* 03 streaming */
.ask{display:flex;justify-content:flex-end;margin-bottom:14px}
.ask span{background:var(--chip);padding:8px 12px;font-size:14px;max-width:85%}
.answer{font-size:15px;line-height:1.65;color:var(--text)}
.cite{display:inline-flex;align-items:center;justify-content:center;min-width:18px;height:18px;padding:0 4px;margin:0 2px;font-family:var(--mono);font-weight:700;font-size:10px;color:var(--accent);background:var(--accent-bg);border:1px solid var(--accent-icon-line);vertical-align:2px}
.src-row{display:flex;align-items:center;justify-content:space-between;padding:10px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);margin-top:16px}
.stack{display:flex;align-items:center;gap:10px}
.stack .sq{display:flex}
.stack .sq b{width:18px;height:18px;border:1px solid var(--bg);margin-left:-5px;display:grid;place-items:center;font-family:var(--mono);font-size:9px;color:#120a02}
.stack .sq b:first-child{margin-left:0}
.acts{display:flex;gap:2px}
.acts button{width:30px;height:30px;display:grid;place-items:center;color:var(--muted);border:1px solid transparent;transition:color .25s,border-color .25s}
.acts button:hover{color:var(--text);border-color:var(--line)}
.acts button.on{color:var(--accent)}
.fu-label{margin:14px 0 6px}
.fu{display:flex;align-items:center;gap:10px;width:100%;padding:9px 0;border-bottom:1px solid var(--line);font-size:14px;color:var(--text-dim);text-align:left;transition:color .25s ease}
.fu:hover{color:var(--accent)}
.fu .ms{font-size:16px;transition:transform .35s var(--ease)}
.fu:hover .ms{transform:translateX(3px)}

/* live answer citation preview */
.st-tip{position:absolute;z-index:6;display:flex;align-items:center;gap:10px;width:230px;padding:10px 12px;background:var(--panel);border:1px solid var(--icon-line);box-shadow:0 14px 34px -16px rgba(0,0,0,.4);opacity:0;transform:translateY(4px);transition:opacity .15s ease,transform .25s var(--ease);pointer-events:none}
.st-tip.show{opacity:1;transform:none}
.st-tip b{display:grid;place-items:center;width:24px;height:24px;flex:none;color:#fff;font-size:11px}
.st-tip .t{font-size:13px;font-weight:600;color:var(--text)}
.st-tip .d{font-size:11.5px;color:var(--muted)}
#c3 .cite{cursor:help}
[data-style="soft"] .st-tip{border-radius:14px;border-color:var(--line)}
[data-style="soft"] .st-tip b{border-radius:50%}

/* live answer sources popover */
#c3 .src-row .stack{cursor:pointer;padding:3px 6px;margin:-3px -6px;transition:background-color .15s}
#c3 .src-row .stack:hover,#c3 .src-row .stack:focus-visible{background:var(--chip);outline:none}
.src-pop{position:absolute;left:0;bottom:calc(100% + 6px);z-index:6;width:260px;padding:4px;background:var(--panel);border:1px solid var(--icon-line);box-shadow:0 16px 36px -16px rgba(0,0,0,.35);opacity:0;visibility:hidden;transform:translateY(4px) scale(.98);transform-origin:bottom left;transition:opacity .18s ease,transform .3s var(--ease),visibility 0s linear .3s}
.src-pop.show{opacity:1;visibility:visible;transform:none;transition:opacity .18s ease,transform .3s var(--ease),visibility 0s}
.src-h{padding:6px 8px 4px}
.src-i{display:flex;align-items:center;gap:10px;width:100%;padding:7px 8px;text-align:left;transition:background-color .15s}
.src-i:hover{background:var(--chip)}
.src-i b{display:grid;place-items:center;width:22px;height:22px;flex:none;color:#fff;font-size:11px}
.src-i .t{display:block;font-size:13px;font-weight:600;color:var(--text)}
.src-i .d{display:block;font-size:11.5px;color:var(--muted)}
.src-i>.ms{margin-left:auto;color:var(--muted)}
[data-style="soft"] #c3 .src-row .stack{border-radius:8px}
[data-style="soft"] .src-pop{border-radius:14px;border-color:var(--line)}
[data-style="soft"] .src-i{border-radius:9px}
[data-style="soft"] .src-i b{border-radius:50%}

/* ---------- 03 streaming ---------- */
const stAnswer = $('#st-answer'), stAfter = $('#st-after');
let stText = 'Most users leave at the workspace setup step {1}, where they are asked to name a team before creating anything. Sessions that skip it reach their first project twice as often {2}. Moving the step after the first project, with the name prefilled from the email domain, keeps the flow to three screens {3}.';
let stTimers = [];
function stream(next){
  if (next) stText = next;
  stTimers.forEach(clearTimeout); stTimers = [];
  stAfter.classList.remove('open');
  // render every word hidden first so the height is final and nothing jumps
  stAnswer.innerHTML = stText.split(' ').map(w => {
    const m = w.match(/^\{(\d)\}(.*)$/);
    return m ? `<span class="w"><span class="cite">${m[1]}</span>${m[2]}</span>` : `<span class="w">${w}</span>`;
  }).join(' ');
  const ws = $$('.w', stAnswer);
  ws.forEach((w, i) => stTimers.push(setTimeout(() => { w.classList.add('in'); if (i % 2 === 0) ambient('c3', 'stream'); }, reduce ? 0 : 200 + i * 50)));
  stTimers.push(setTimeout(() => { stAfter.classList.add('open'); ambient('c3', 'pop'); }, reduce ? 0 : 200 + ws.length * 50 + 300));
}
$('#st-play').addEventListener('click', () => { Sound.play('tab'); stream(); });
$('#st-replay').addEventListener('click', () => { Sound.play('tab'); stream(); });
$$('#c3 .acts [data-act]').forEach(b => b.addEventListener('click', async () => {
  if (b.dataset.act === 'copy'){ if (await copyText(stAnswer.textContent)) { Sound.play('copy'); showToast('Copied'); } }
  else { $$('#c3 .acts [data-act="rate"]').forEach(x => x.classList.toggle('on', x === b)); Sound.play('select'); }
}));
  if ('IntersectionObserver' in window){
  const io = new IntersectionObserver(es => es.forEach(e => { if (e.isIntersecting){ stream(); io.disconnect(); } }), {threshold:.4});
  io.observe(stAnswer);
} else stream();

/* ---------- live answer extras ---------- */
{
  const panel = $('#st-answer').closest('.panel'), ask = $('#c3 .ask span');
  const SRC = { 1:['F','#ff850d','Onboarding flow.fig','Figma, frames 4 to 9'], 2:['N','#7a7f96','Q3 research notes','Notion, 12 interviews'], 3:['S','#4a8cff','Activation funnel','Segment, last 30 days'] };
  const tip = document.createElement('div'); tip.className = 'st-tip'; panel.style.position = 'relative'; panel.appendChild(tip);
  $('#st-answer').addEventListener('mouseover', e => {
    const c = e.target.closest('.cite'); if (!c) return; const s = SRC[c.textContent.trim()]; if (!s) return;
    tip.innerHTML = `<b style="background:${s[1]}">${s[0]}</b><div><div class="t">${s[2]}</div><div class="d">${s[3]}</div></div>`;
    const pr = panel.getBoundingClientRect(), cr = c.getBoundingClientRect();
    tip.style.left = Math.max(8, Math.min(pr.width - 240, cr.left - pr.left - 20)) + 'px'; tip.style.top = (cr.top - pr.top - 52) + 'px';
    tip.classList.add('show'); Sound.play('stream');
  });
  $('#st-answer').addEventListener('mouseout', e => { if (e.target.closest('.cite')) tip.classList.remove('show'); });
  const FOLLOW = {
    'Show the drop-off by device':'Mobile users drop off most at the workspace step {1}, about twice the desktop rate. Most of them arrive from the invite email {2}, so a shorter mobile setup would recover the most people {3}.',
    'Draft a fix for the workspace step':'Move workspace naming after the first project {1}. Prefill the name from the email domain {2}, keep it editable in settings, and cut setup to three screens {3}.',
    'Compare against last quarter':'Drop-off at the workspace step rose since last quarter {3}, after the extra team field was added {1}. Interviews point to the same moment of hesitation {2}.'
  };
  $$('#c3 .fu').forEach(b => b.addEventListener('click', () => {
    const q = b.textContent.trim(); Sound.play('send'); swapText(ask, q);
    const left = Object.keys(FOLLOW).filter(k => k !== q);
    $$('#c3 .fu').forEach((f, i) => { f.innerHTML = `${ic('chevron_right')}${left[i]}`; });
    stream(FOLLOW[q]);
  }));
}

/* ---------- live answer sources ---------- */
{
  const stack = $('#c3 .src-row .stack'), row = stack.parentElement;
  stack.setAttribute('tabindex', '0'); stack.setAttribute('role', 'button'); stack.setAttribute('aria-label', 'Show sources');
  const panel = stack.closest('.panel'), pop = document.createElement('div'); pop.className = 'src-pop'; panel.style.position = 'relative'; panel.appendChild(pop);
  const SRC = [['F','#ff850d','Onboarding flow.fig','Figma, frames 4 to 9'],['N','#c9c9d6','Q3 research notes','Notion, 12 interviews'],['S','#7a7f96','Activation funnel','Segment, last 30 days']];
  pop.innerHTML = '<div class="src-h mono-xs">Sources</div>' + SRC.map((s, i) => `<button class="src-i"><b style="background:${s[1]}">${s[0]}</b><span><span class="t">${i + 1}. ${s[2]}</span><span class="d">${s[3]}</span></span>${ic('open_in_new','sm')}</button>`).join('');
  let t = null;
  // the popover sits on the panel so the unfolding area below can't clip it
    const place = () => { const pr = panel.getBoundingClientRect(), sr = stack.getBoundingClientRect(); pop.style.left = (sr.left - pr.left) + 'px'; pop.style.top = (sr.top - pr.top - pop.offsetHeight - 8) + 'px'; };
    const show = () => { clearTimeout(t); place(); if (!pop.classList.contains('show')){ pop.classList.add('show'); Sound.play('stream'); } };
  const hide = () => { t = setTimeout(() => pop.classList.remove('show'), 160); };
  [stack, pop].forEach(el => { el.addEventListener('mouseenter', show); el.addEventListener('mouseleave', hide); });
  stack.addEventListener('click', () => pop.classList.contains('show') ? pop.classList.remove('show') : show());
  stack.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' '){ e.preventDefault(); show(); } if (e.key === 'Escape') pop.classList.remove('show'); });
  pop.addEventListener('click', e => { const b = e.target.closest('.src-i'); if (b){ Sound.play('tab'); showToast('Opening ' + b.querySelector('.t').textContent.replace(/^\d+\. /, '')); } });
}
